import ast
import operator

class SafeEvaluator(ast.NodeVisitor):
    # 使用を許可する演算子
    operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }

    def visit(self, node):
        if isinstance(node, ast.Expression):
            return self.visit(node.body)
        elif isinstance(node, ast.Constant):  # 数値リテラル (Python 3.8+)
            if isinstance(node.value, (int, float)):
                return node.value
            raise TypeError(f"サポートされていない型です: {type(node.value)}")
        elif isinstance(node, ast.BinOp):  # 二項演算 (例: a + b)
            left = self.visit(node.left)
            right = self.visit(node.right)
            op_type = type(node.op)
            if op_type in self.operators:
                return self.operators[op_type](left, right)
            raise TypeError(f"サポートされていない演算子です: {op_type}")
        elif isinstance(node, ast.UnaryOp):  # 単項演算 (例: -1, +5)
            operand = self.visit(node.operand)
            op_type = type(node.op)
            if op_type in self.operators:
                return self.operators[op_type](operand)
            raise TypeError(f"サポートされていない単項演算子です: {op_type}")
        else:
            raise TypeError(f"サポートされていない構文です: {type(node)}")

def eval_expression(expr: str):
    """
    文字列の数式を安全に計算する関数。
    演算の順序、カッコ、負の数を考慮し、ゼロ除算の場合は ZeroDivisionError を送出する。
    """
    try:
        # 文字列を抽象構文木(AST)にパースする
        tree = ast.parse(expr, mode='eval')
    SyntaxError:
        raise ValueError(f"無効な数式です: {expr}")

    evaluator = SafeEvaluator()
    return evaluator.visit(tree)

# --- 使用例・テスト ---
if __name__ == "__main__":
    print(eval_expression("3 + 4 * (2 - 1)"))       # 出力: 7.0 (または 7)
    print(eval_expression("-5 + 3 * -2"))          # 出力: -11
    print(eval_expression("(10 - 2) / (2 + 2)"))   # 出力: 2.0

    # ゼロ除算のテスト
    try:
        print(eval_expression("5 / 0"))
    except ZeroDivisionError:
        print("ZeroDivisionError が正しく捕捉されました。")
